module tb_TopModule;
    logic [4:0] a, b, c, d, e, f;
    logic [7:0] w, x, y, z;

    TopModule dut (
        .a(a), .b(b), .c(c), .d(d), .e(e), .f(f),
        .w(w), .x(x), .y(y), .z(z)
    );

    initial begin
        integer i;
        logic [31:0] expected;

        for (i = 0; i < 100; i = i + 1) begin
            a = $random;
            b = $random;
            c = $random;
            d = $random;
            e = $random;
            f = $random;
            #1;
            expected = {a, b, c, d, e, f, 2'b11};
            if ({w, x, y, z} !== expected) begin
                $display("SELFTEST FAIL: at i=%0d, expected %h, got %h", i, expected, {w, x, y, z});
                $finish;
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
